{
  "name": "thought-chain-doc",
  "private": true,
  "version": "2.10.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "@ant-design/icons": "^6.0.0",
    "@ant-design/x": "^2.10.0",
    "antd": "^6.7.0",
    "react": "^18.3.1",
    "react-dom": "^18.3.1",
    "react-router-dom": "^6.30.0"
  },
  "devDependencies": {
    "@types/react": "^18.3.12",
    "@types/react-dom": "^18.3.1",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.6.3",
    "vite": "^6.0.5"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  base: './',
  plugins: [react()],
  build: {
    outDir: 'dist',
    assetsInlineLimit: 4096,
  },
});

{
  "files": [],
  "references": [
    { "path": "./tsconfig.app.json" },
    { "path": "./tsconfig.node.json" }
  ]
}

:root {
  --x-font-family: -apple-system, 'system-ui', 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji',
    'Segoe UI Symbol', 'Noto Color Emoji';
  --x-font-mono: SFMono-Regular, Consolas, 'Liberation Mono', Menlo, Courier,
    monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--x-font-family);
  font-size: 14px;
  line-height: 1.5715;
  color: rgba(0, 0, 0, 0.88);
  background: #ffffff;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
}

a {
  color: #1677ff;
  text-decoration: none;
  background-color: transparent;
}

a:hover {
  color: #4096ff;
}

code,
kbd,
pre,
samp {
  font-family: var(--x-font-mono);
}

/* Thin scrollbars used by the side menus */
.x-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.x-scroll::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.12);
  border-radius: 3px;
}
.x-scroll::-webkit-scrollbar-track {
  background: transparent;
}

/* prevent the whole doc frame from scrolling sideways on small screens */
html,
body {
  overflow-x: hidden;
}

