const sharp = require('sharp');
const src = '/Users/lixing/WorkRep/TodoList/craft-projects/x-ant-design/capture/screenshot-1440.png';
(async () => {
  // Sample pixels on demo1 titles/descriptions (crop was x348, y510). Use absolute coords.
  // In demo1.png (928 wide, top510): item1 title at ~x105,y55 -> abs x453,y565
  // Let's read a strip and find dark pixels per row.
  const { data, info } = await sharp(src)
    .extract({left:348, top:510, width:600, height:400})
    .raw().toBuffer({resolveWithObject:true});
  const channels = info.channels;
  const px = (x,y) => {
    const i=(y*info.width+x)*channels;
    return [data[i],data[i+1],data[i+2]];
  };
  // item1 title baseline row ~55: scan
  const samples = [
    ['item1 title', 105, 56],
    ['item1 desc', 105, 96],
    ['item2 title', 105, 150],
    ['item3 title', 105, 245],
    ['item4 title', 105, 340],
    ['item4 desc', 105, 370],
