import type { ReactNode } from 'react';
import './ApiTable.css';

export interface ApiRow {
  name: ReactNode;
  desc: ReactNode;
  type: ReactNode;
  def?: ReactNode;
  version?: ReactNode;
}

export default function ApiTable({ rows }: { rows: ApiRow[] }) {
  return (
    <div className="api-table x-scroll">
      <table>
        <thead>
          <tr>
            <th>属性</th>
            <th>说明</th>
            <th>类型</th>
            <th>默认值</th>
            <th>版本</th>
