        <tbody>
          {rows.map((r, i) => (
            <tr key={i}>
              <td className="api-name">{r.name}</td>
              <td>{r.desc}</td>
              <td className="api-type">{r.type}</td>
              <td>{r.def ?? '-'}</td>
              <td>{r.version ?? '-'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** Type-text helper: magenta monospace fragment. */
export function T({ children }: { children: ReactNode }) {
