export interface Token {
  name: string;
  desc: string;
  type: string;
  def: string;
  /** hex/rgba for the swatch dot; omit for non-color tokens */
  color?: string;
}

function TokenRows({ tokens }: { tokens: Token[] }) {
  return (
    <>
      {tokens.map((t) => (
        <tr key={t.name}>
          <td className="tok-name">{t.name}</td>
          <td>{t.desc}</td>
